        ru: 'Если ты не можешь говорить в назначенное время, скажи прямо: "That doesn\'t work for me" — «мне это не подходит». Или предложи своё время: "Can we meet at 10 a.m. my time?" — «можем встретиться в 10 утра по моему времени?». Коротко — и всё понятно.',
