        uk: 'Коли хочеш купити щось у магазині, кажи: I need (мені потрібно) або I want to buy (я хочу купити). Після них — просто називай потрібний товар. Усе просто.',
        es: 'Cuando quieres comprar algo en la tienda, di: I need (necesito) o I want to buy (quiero comprar). Después nombra el producto. Es sencillo.',
